    capture.active=false;if(capture.ps[0] && strcmp(kind,"draw"))return false;if(capture.trace && (capture.frame==present+1 || capture.frame==UINT64_MAX) && capture.seen++>=capture.skip)capture.active=capture.events<capture.maxev;
    if(capture.active){++capture.events;capture_log("EVENT frame=%llu event=%u kind=%s",(unsigned long long)capture.frame,capture.events,kind);}
