inline int bucket(uint32_t s){return s<=12?0:s<=16?1:s<=24?2:s<=32?3:s<=48?4:5;}
void report(double f){if(on<=0)return;for(int k=0;k<2;k++){const double d=draws[k]?double(draws[k]):1.0;
    xbg_logf("NVN PERF vtxstats %s draws=%.1f idx=%.0f stride_avg=%.1f bytes_mb=%.1f hist<=12/16/24/32/48/more=%llu/%llu/%llu/%llu/%llu/%llu multi_stream=%.1f u8_index=%.1f nonindexed=%.1f instanced=%.1f",
        k?"colour":"depth-only",draws[k]/f,idx[k]/f,idx[k]?double(bytes[k])/double(idx[k]):0.0,bytes[k]/1048576.0/f,(unsigned long long)hist[k][0],(unsigned long long)hist[k][1],(unsigned long long)hist[k][2],(unsigned long long)hist[k][3],(unsigned long long)hist[k][4],(unsigned long long)hist[k][5],multi[k]/f,u8[k]/f,plain[k]/f,inst[k]/f);(void)d;}
    for(int k=0;k<2;k++){draws[k]=idx[k]=bytes[k]=multi[k]=u8[k]=plain[k]=inst[k]=0;for(auto &h:hist[k])h=0;}}
