    void *tmp=mmap(nullptr,n,PROT_READ|PROT_WRITE,flags,-1,0);if(tmp==MAP_FAILED){xbg_logf("NVN zero-copy: restore of %#lx+%#zx: mmap failed errno=%d, chunk kept",(unsigned long)lo,n,errno);return false;}
