    if(p->mem_type==UINT32_MAX || vkAllocateMemory(cfg.device,&ai,nullptr,&p->memory)!=VK_SUCCESS){p->memory=VK_NULL_HANDLE;destroy(p);++w_refused[R_MEMORY];return nullptr;}
