        case 43:if(n>=4)constant[w[i+2]]=w[i+3];break; // OpConstant (32-bit)
        case 30:if(n>=3)struct_member0[w[i+1]]=w[i+2];break; // OpTypeStruct member 0
        case 32:if(n>=4)pointer_pointee[w[i+1]]=w[i+3];break;
