// [ETERNAL nx2b] DM_GFX_DYN_STATE (ETR: 0x1 blend constants / stencil masks + references / depth bias / line width as dynamic states, 0x2 POD pipeline map).
// Only 0x2 is ported (0x1 changes the pipelines and the warm-up list format: not taken, the bit is ignored and logged). 0x2: a map from the full
// pipeline-memo key (raw bytes, memcmp) to its pipeline, looked up in DM_GFX_DRAW_FAST's fast block when the previous draw's key differs (A B A B
// pipelines: the previous-draw memo misses, the CreateInfo build + pipeline_fast lookup ran). Its keys are the memo's, so a hit returns the pipeline the
// slow path's memo would have returned for an equal previous draw; entries go wherever pipeline_fast entries go (eviction, descriptor / pass / pipeline
// cache clears). DRAW_FAST=2 verifies POD hits too. Default 2 for DM_GAME_DOS2, 0 elsewhere. NVN PERF drawfast pod_hits / pod_misses / pod_size.
struct PodHash{size_t operator()(const PipeMemoKey &k)const{const uint8_t *b=reinterpret_cast<const uint8_t*>(&k);uint64_t h=1469598103934665603ull,w;size_t i=0;for(;i+8<=sizeof k;i+=8){memcpy(&w,b+i,8);h=(h^w)*1099511628211ull;}for(;i<sizeof k;i++)h=(h^b[i])*1099511628211ull;return size_t(h^(h>>29));}};
struct PodEq{bool operator()(const PipeMemoKey &a,const PipeMemoKey &b)const{return !memcmp(&a,&b,sizeof a);}};
std::unordered_map<PipeMemoKey,VkPipeline,PodHash,PodEq> pipe_pod;
int dyn_state_mode(){static const int v=[]{const char *e=getenv("DM_GFX_DYN_STATE");
#ifdef DM_GAME_DOS2
    int x=2;
#else
    int x=0;
#endif
    if(e && *e)x=int(strtol(e,nullptr,0))&3;
    if(x&1)xbg_logf("NVN DM_GFX_DYN_STATE bit 0x1 (dynamic blend constants / stencil / depth bias / line width) is not ported to this tree: ignored");
    x&=2;xbg_logf("NVN DM_GFX_DYN_STATE=%d (0x2 POD pipeline map in DM_GFX_DRAW_FAST's fast block)",x);return x;}();return v;}
inline bool pipe_pod_on(){return (dyn_state_mode()&2)!=0;}
inline VkPipeline pipe_pod_find(const PipeMemoKey &k){auto f=pipe_pod.find(k);return f!=pipe_pod.end()?f->second:VK_NULL_HANDLE;}
inline void pipe_pod_store(const PipeMemoKey &k,VkPipeline p){if(pipe_pod.size()>=65536)pipe_pod.clear();pipe_pod[k]=p;++pipe_pod_stores;}
void pipe_pod_erase(VkPipeline old){for(auto f=pipe_pod.begin();f!=pipe_pod.end();)if(f->second==old)f=pipe_pod.erase(f);else ++f;nbpipe::erase(old);}
uint64_t draw_fast_checks=0,draw_fast_bad=0,draw_fast_unbuilt=0;
void draw_fast_verify(VkPipeline expected,VkPipeline got){++draw_fast_checks;
    if(!got){++draw_fast_unbuilt;return;}   // the full lookup skipped the draw (async build): nothing to compare
    if(got!=expected && ++draw_fast_bad<=8)xbg_logf("【红】NVN DM_GFX_DRAW_FAST verify: the memo key gave pipeline %p, the full lookup %p (vs=%s ps=%s prim key equal; frame %llu)",(void*)expected,(void*)got,
        state.shader[0]?state.shader[0]->key.c_str():"-",state.shader[4]?state.shader[4]->key.c_str():"-",(unsigned long long)stats.presents.load());}
void draw_fast_report(double f){if(!draw_fast_mode() && !pipe_pod_on())return;
    xbg_logf("NVN PERF drawfast mode=%d dyn=%d per_frame hits=%.1f pod_hits=%.1f pod_misses=%.1f pod_stores=%.2f pod_size=%zu verify checks=%llu bad=%llu unbuilt=%llu",draw_fast_mode(),dyn_state_mode(),
        pipe_draw_fast_hits/f,pipe_pod_hits/f,pipe_pod_misses/f,pipe_pod_stores/f,pipe_pod.size(),(unsigned long long)draw_fast_checks,(unsigned long long)draw_fast_bad,(unsigned long long)draw_fast_unbuilt);
    pipe_draw_fast_hits=pipe_pod_hits=pipe_pod_misses=pipe_pod_stores=0;}
