    const std::string path=std::string(cfg.shader_directory)+"/shaders.xgspack";const uint64_t t0=timing_clock();int f=::open(path.c_str(),O_RDONLY|O_CLOEXEC);if(f<0){xbg_logf("NVN shader pack %s: none (bundles read one file each)",path.c_str());return;}
    struct stat st{};uint32_t h[4]={};bool ok=!fstat(f,&st) && pread(f,h,16,0)==16 && h[0]==0x50534758u && h[1]==1u && h[2]<(1u<<22);
