    for(auto &x:pend){bool dup=false;for(auto &y:r.in)if(y.img==x.img && y.how==x.how && y.sh==x.sh && y.bind==x.bind){dup=true;break;}if(!dup){if(r.in.size()<64)r.in.push_back(x);else ++rd_lost;}}pend.clear();
