bool skip_unusable(const char *what){   // [nonadreno] (from the DOOM 2016 port) a bound module lacks a device capability (Shader::unusable): skip, logged per module
    for(unsigned st=0;st<6;st++){Shader *sh=state.shader[st];if(what[0]=='d' && st==5)continue;if(what[0]=='c' && st!=5)continue;
        if(sh && !sh->unusable.empty()){static std::unordered_set<std::string> told;if(told.insert(sh->key).second)xbg_logf("NVN %s skipped: shader %s stage %u needs %s",what,sh->key.c_str(),st,sh->unusable.c_str());return true;}}
    return false;}
// [ETERNAL xlat] DM_GFX_DESC_RECYCLE (ETR cmp16 906cc4d; default 1 for DM_GAME_DOS2, 0 elsewhere = as before; 1 on; 2 verify). Every draw takes a
// Descriptors record (acquire_descriptors) that stays with the slot until its fence (release_descriptors): ~2200 records a DOS2 menu frame, each last
// touched two submissions of that slot ago, so what the draw writes into it (set, layout, dynamic offsets, the kept vertex / index / block Buffers) and
// the release loop work on cold memory. Nothing reads a draw's record after draw() returns unless it holds texel buffer views (destroyed at the fence),
// capture inputs or storage writebacks: the Buffers it keeps are value copies of arena / stream ranges that live with the slot, the descriptor memo and
// pending writebacks copy what they need. Mode 1: such a record goes back to the free list at the end of draw(), so the next draw takes the same, warm
// one. Not recycled: a record that is not the last one of the recording slot (the submission ended inside the draw), one with buffer views / capture
// inputs / storage writes, and any draw while a capture or the provenance file is active. Mode 2 (verify): nothing is recycled; the record's digest at
// the end of draw() is compared when the slot releases it: a difference = something wrote the record after its draw (bad=, the first 8 are logged).
// A late reader that only reads is not detected by it. ETR fast12: -0.27 us/draw, verify 3.3M checks bad=0. NVN PERF descrecycle.
namespace drecy{
int mode=-1;uint64_t recycled=0,kept[3]={},checks=0,bad=0;
inline int get(){if(mode<0){const char *e=getenv("DM_GFX_DESC_RECYCLE");
#ifdef DM_GAME_DOS2
    mode=1;
#else
    mode=0;
#endif
    if(e && *e)mode=std::clamp(atoi(e),0,2);xbg_logf("NVN DM_GFX_DESC_RECYCLE=%d (1: a draw's descriptor record returns to the free list when the draw ends, 2: verify only)",mode);}return mode;}
uint64_t sig(const Descriptors &d){uint64_t h=0x9E3779B97F4A7C15ull;auto mix=[&](uint64_t v){h=(h^v)*0x100000001B3ull;h^=h>>29;};
    mix(uint64_t(uintptr_t(d.entry)));mix(uint64_t(uintptr_t(d.set)));mix(uint64_t(uintptr_t(d.pipeline_layout)));
    mix(d.dynamic_offsets.size());for(uint32_t o:d.dynamic_offsets)mix(o);
    mix(d.buffers.size());for(const Buffer &b:d.buffers){mix(uint64_t(uintptr_t(b.buffer)));mix(b.offset);mix(b.size);}
    mix(d.buffer_views.size());mix(d.storage.size());mix(d.written.size());mix(d.capture_inputs.size());return h|1;}
void check(Descriptors *d){++checks;
    if(sig(*d)!=d->rsig && ++bad<=8)xbg_logf("【红】NVN desc-recycle verify: a draw's descriptor record changed after its draw (entry %p set %p offsets %zu buffers %zu written %zu views %zu)",(const void*)d->entry,(void*)d->set,d->dynamic_offsets.size(),d->buffers.size(),d->written.size(),d->buffer_views.size());
    d->rsig=0;}
inline void done(Descriptors &d){const int m=get();if(!m)return;
    Slot &s=slots[slot_index];
    if(s.desc_used.empty() || s.desc_used.back()!=&d){++kept[0];return;}
    if(!d.buffer_views.empty() || !d.capture_inputs.empty() || !d.written.empty()){++kept[1];return;}
    if(capture.active || provenance_file){++kept[2];return;}
    if(m==2){d.rsig=sig(d);return;}
    s.desc_used.pop_back();desc_reset(&d);desc_free.push_back(&d);++recycled;}
void report(double f){if(mode<=0 && !recycled && !checks)return;
    xbg_logf("NVN PERF descrecycle mode=%d per_frame recycled=%.1f kept: not_last=%.1f views_or_writes=%.1f other_path=%.1f | records=%zu free=%zu | verify checks=%llu bad=%llu",
        mode,recycled/f,kept[0]/f,kept[1]/f,kept[2]/f,desc_all.size(),desc_free.size(),(unsigned long long)checks,(unsigned long long)bad);
    recycled=0;for(auto &x:kept)x=0;}
}
void drecy_report(double f){drecy::report(f);}
