        int ix0=std::clamp(int(std::lround(x0)),0,int(w)),ix1=std::clamp(int(std::lround(x1)),0,int(w)),iy0=std::clamp(int(std::lround(y0)),0,int(h)),iy1=std::clamp(int(std::lround(y1)),0,int(h));
