void execute_indirect(const xbg_indirect &p,bool single){preflight_cpu_reads();
    need(p.arguments && p.max_count>=0 && p.max_count<=1000000,"Invalid indirect draw request");
    if(gpu_indirect_try(p,single))return;
    uint32_t count=1;
    if(!single){
        need(p.count_address && !(p.count_address&3),"Invalid indirect count address");
        need(command_available(reinterpret_cast<const uint8_t*>(p.count_address))>=4,"Truncated indirect count storage");
        cpu_access(p.count_address,4,5);memcpy(&count,reinterpret_cast<const void*>(p.count_address),4);count=std::min(count,uint32_t(p.max_count));
    }
    for(uint32_t i=0;i<count;i++){
        uint64_t address=0;need(xbg_draw_indirect_address(p.arguments,i,p.stride,p.index_type,&address)==0,"Invalid indirect argument address/stride");
        size_t bytes=p.index_type<0?16:20;
        need(bytes<=command_available(reinterpret_cast<const uint8_t*>(address)),"Indirect arguments exceed registered storage");cpu_access(address,bytes,5);
        // Read at execution, after preceding synchronous GPU storage writeback,
        // never at command recording. Both single and multi use this path.
        xbg_draw_call plan{};int result=xbg_draw_indirect_plan(&plan,p.primitive,p.index_type,p.index_address,reinterpret_cast<const void*>(address),bytes);
        if(result)xbg_fatalf("Invalid indirect draw parameters: %d",result);
        if((gscull_mask()&0x100) && p.index_type>0 && !gscull_ranges.empty()){auto it=gscull_ranges.upper_bound(p.index_address);
            if(it!=gscull_ranges.begin() && p.index_address<(--it)->first+it->second){uint32_t v[5];memcpy(v,reinterpret_cast<const void*>(address),20);++gscull_checked;
                const uint64_t end=p.index_address+((uint64_t(v[2])+v[0])<<p.index_type),cap=it->first+it->second;
                if(end>cap || v[0]%3 || p.index_address!=it->first){++gscull_bad;static unsigned n=0;if(n++<60)xbg_logf("NVN GS-cull args idx=%#llx range=%#llx+%llu count=%u inst=%u first=%u base=%d over=%lld (checked %llu bad %llu)",(unsigned long long)p.index_address,(unsigned long long)it->first,(unsigned long long)it->second,v[0],v[1],v[2],int32_t(v[3]),(long long)(end-cap),(unsigned long long)gscull_checked,(unsigned long long)gscull_bad);}
                else{static unsigned ok=0;if(ok++%5000==0)xbg_logf("NVN GS-cull args ok checked=%llu bad=%llu (last count=%u of %llu)",(unsigned long long)gscull_checked,(unsigned long long)gscull_bad,v[0],(unsigned long long)(it->second>>p.index_type));}}}
        execute_draw_call(plan);
    }
}
template<class T>T payload(const uint8_t *p,size_t n){need(n>=sizeof(T),"Truncated NVN command payload");T out;memcpy(&out,p,sizeof(out));return out;}
template<class T>T variable_payload(const uint8_t *p,size_t n){T out{};memcpy(&out,p,std::min(n,sizeof(T)));return out;}
// Graphics thread: retire submitted slots whose fence already signalled (non-blocking) so a game
// thread blocked on an older fence is released while the next frame is still being translated.
void poll_retire(){
    bool any=false;for(int i=0;i<slot_count;i++){Slot &s=slots[i];if(s.pending && !s.recording && vkGetFenceStatus(cfg.device,s.fence)==VK_SUCCESS){retire_slot(s);any=true;}}
    if(any){{std::lock_guard<std::mutex> l(gfx_job_mutex);}gfx_idle_cv.notify_all();}
}
// [D3] DM_GFX_IDLE_RETIRE: retire, without blocking, the slots whose fence signalled, oldest submission first (writebacks,
// reports and events land in order; poll_retire's index order could retire the newer slot first). Caller holds the engine.
unsigned retire_signalled(){
    unsigned n=0;
    for(int i=0;i<slot_count;i++){Slot *op=oldest_pending();if(!op)break;Slot &o=*op;
        if(o.recording)break;
        if(vkGetFenceStatus(cfg.device,o.fence)!=VK_SUCCESS){
            // [D3] breadcrumb (crash reports / hangs): the oldest submission still unsignalled after 2 s of idle polling, once per submission
            static uint64_t wait_serial=0,wait_t0=0,told_serial=0;const uint64_t now=timing_clock();
            if(o.covers!=wait_serial){wait_serial=o.covers;wait_t0=now;}
            else if(now-wait_t0>2000000000ull && told_serial!=o.covers){told_serial=o.covers;xbg_logf("NVN idle retire: submission %llu not signalled after %.1f s of idle polling (GPU still busy or hung; DM_GFX_CRUMBS=1 names the work)",(unsigned long long)o.covers,(now-wait_t0)/1e9);}
            break;}
        SiteScope site(SITE_IDLE);retire_slot(o);++n;}
    if(n){static bool first=true;if(first){first=false;xbg_logf("NVN idle retire: first submission retired by the translate thread on its own (mode %d)",idle_retire);}}   // [D3] breadcrumb
    idle_retired+=n;return n;
}
// The recording slot holds deferred results (a SignalEvent kept by gfx-defer-events 2, or a counter report) that only its
// submission and retirement will publish.
bool recording_holds_results(){
    const Slot &cur=slots[slot_index];if(!cur.recording || !cur.ops)return false;
    if(!recording_events.empty())return true;
    for(const auto &r:pending_reports)if(r.slot==&cur)return true;
    return false;
}
// The effect of the bind records, shared by execute() and the OP_X_NB_DRAW unpack ([DOS2] NB-09, xbg_nb.inc nbdraw): same checks, same
// tables, same generation counters. n = payload bytes of the record (a bind-handles record carries only its first a.n handles).
